// Skip anyone we must not email, whatever their lifecycle says. A bounced
// address and an explicit opt-out both outrank a campaign.
return $input.all().filter((item) => {
  const c = item.json;
  if (!c.email) return false;
  if (c.bounced_at) return false;
  if (c.unsubscribed_at) return false;
  return true;
});

// Pair each send result back up with the contact it went to, and pull out the
// Message-ID. That id is the entire basis of thread-accurate reply matching:
// without it the CRM can still match a reply by from-address, but it cannot
// tell which campaign the reply answers, and it misses anyone who writes back
// from a different address.
//
// nodemailer surfaces the id under different keys depending on the n8n
// version, so every plausible spelling is checked before giving up.

const out = [];

for (let i = 0; i < $input.all().length; i++) {
  const sent = $input.all()[i].json;
  const contact = $('Drop bounced and opted-out').all()[i].json;

  const messageId =
    sent.messageId || sent.message_id || sent.messageID || null;

  if (!messageId) {
    // Loud on purpose. Silently losing threading is the failure mode that is
    // hardest to notice later, because replies still half-work.
    console.warn(
      `No Message-ID returned for ${contact.email}. Reply matching for this ` +
      `message will fall back to the from-address.`,
    );
  }

  out.push({
    json: {
      message_id: messageId,
      contact_email: contact.email,
      subject: sent.subject || null,
      sent_at: new Date().toISOString(),
      _skip: !messageId,
    },
  });
}

// Nothing to record without an id — the CRM requires one.
return out.filter((item) => !item.json._skip);
